// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
export type Density = "comfortable" | "compact" | "calm";
export type Motion = "system" | "reduced";
export type PaperChoice = "plain" | "ruled" | "graph" | "dots" | "kraft";
export type Direction = "ltr" | "rtl";
export type Appearance = {
  theme: string;
  density: Density;
  motion: Motion;
  fine: boolean;
  paper: PaperChoice;
  dir: Direction;
};
export const DEFAULT_APPEARANCE: Appearance = {
  theme: "notebook" as const,
  density: "comfortable" as const,
  motion: "system" as const,
  fine: false,
  paper: "ruled" as const,
  dir: "ltr" as const
};
export const THEMES = [{
  id: "notebook" as const,
  name: "Notebook" as const,
  help: "Cream paper, felt tip, terracotta marker." as const,
  ready: true
}, {
  id: "forest" as const,
  name: "Forest" as const,
  help: "Sage felt, kraft slips, petrol-teal ink." as const,
  ready: false
}, {
  id: "zine" as const,
  name: "Zine" as const,
  help: "Lilac mat, louder stickers, heavier pens." as const,
  ready: false
}];
export const DENSITIES: {
  id: Density;
  name: string;
  help: string;
}[] = [{
  id: "comfortable" as const,
  name: "Comfortable" as const,
  help: "Roomy controls, the full hand-drawn wobble." as const
}, {
  id: "compact" as const,
  name: "Compact" as const,
  help: "Tighter controls for people who like to see more." as const
}, {
  id: "calm" as const,
  name: "Calm" as const,
  help: "Hairline pencil, no wobble, no tilt. For tables and long forms." as const
}];
export const MOTIONS: {
  id: Motion;
  name: string;
  help: string;
}[] = [{
  id: "system" as const,
  name: "Follow my device" as const,
  help: "Ink is written on, paper settles. Off when your device asks for less motion." as const
}, {
  id: "reduced" as const,
  name: "Keep it still" as const,
  help: "Everything just appears, finished." as const
}];
export const PAPERS: {
  id: PaperChoice;
  name: string;
}[] = [{
  id: "plain" as const,
  name: "Plain" as const
}, {
  id: "ruled" as const,
  name: "Ruled" as const
}, {
  id: "graph" as const,
  name: "Graph" as const
}, {
  id: "dots" as const,
  name: "Dots" as const
}, {
  id: "kraft" as const,
  name: "Kraft" as const
}];
export function providerProps(a: Appearance) {
  return {
    density: a.density,
    motion: a.motion,
    tier: a.fine ? "hi" as const : "lo" as const,
    dir: a.dir,
    theme: a.theme === "notebook" ? undefined : a.theme
  };
}
export function providerSnippet(a: Appearance): string {
  const attrs: string[] = [];
  if (a.theme !== "notebook") attrs.push(`theme="${a.theme}"`);
  if (a.density !== "comfortable") attrs.push(`density="${a.density}"`);
  if (a.motion !== "system") attrs.push(`motion="${a.motion}"`);
  if (a.fine) attrs.push(`tier="hi"`);
  if (a.dir !== "ltr") attrs.push(`dir="${a.dir}"`);
  const open = attrs.length ? `<InkProvider ${attrs.join(" ")}>` : "<InkProvider>" as const;
  return `import { InkProvider } from "@/lib/ink/vue"\n\n${open}\n  <App />\n</InkProvider>`;
}

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, useId } from "vue";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Paper } from "@/components/ui/paper";
import { Progress } from "@/components/ui/progress";
import { Switch } from "@/components/ui/switch";
import { Tally } from "@/components/ui/tally";
import { InkProvider } from "@/lib/ink/vue";
import { cn } from "@/lib/utils";
import { providerProps, type Appearance, type PaperChoice } from "@/blocks/settings-appearance/components/settings-appearance-options";
const STOCK: Record<PaperChoice, {
  stock: "paper" | "graph" | "dot-grid" | "kraft";
  rules?: "ruled" | "none";
}> = {
  plain: {
    stock: "paper" as const,
    rules: "none" as const
  },
  ruled: {
    stock: "paper" as const,
    rules: "ruled" as const
  },
  graph: {
    stock: "graph" as const
  },
  dots: {
    stock: "dot-grid" as const
  },
  kraft: {
    stock: "kraft" as const,
    rules: "none" as const
  }
};
export const SettingsAppearancePreview = defineUi<{
  appearance: Appearance;
}>("SettingsAppearancePreview", ["appearance"], (_props, {
  slots: _slots
}) => {
  const appearance = computed(() => _props["appearance"]);
  const id = useId();
  const paper = computed(() => STOCK[appearance.value.paper]);
  const ruled = computed(() => paper.value.rules === "ruled");
  return () => {
    return <InkProvider {...domProps(providerProps(appearance.value))}>
      <div dir={appearance.value.dir} role="region" aria-label="Preview">
        <Paper stock={paper.value.stock} rules={paper.value.rules} seed="appearance-preview" class={cn("grid gap-4 p-5 pt-6", ruled.value && "pt-4 ps-14 rtl:[&>[data-slot=paper-rules]]:-scale-x-100")} tape="top">
          <div class={cn("grid", !ruled.value && "gap-4")}>
            <h3 class={cn("font-script text-2xl font-semibold", ruled.value ? "relative top-[calc(3px-var(--ll-rule-offset,8px))] leading-7 calm:top-[calc(1px-var(--ll-rule-offset,6px))] calm:leading-6" as const : "leading-none" as const)}>Field notes</h3>
            <p class={cn("text-[15px]", ruled.value && "leading-7 calm:leading-6")}>Tuesday. Rain on the window, three cups of tea, and one very small plan for a very big week.</p>
          </div>
          <div class="flex flex-wrap items-center gap-2">
            <Button size="sm">Save</Button>
            <Button size="sm" variant="outline">
              Cancel
            </Button>
            <Badge>3 new</Badge>
            <Tally count={7} size="sm" label="7 pages" />
          </div>
          <Input aria-label="Add a tag" placeholder="Add a tag" />
          <div class="flex items-center gap-2">
            <Checkbox id={`${id}-c`} defaultChecked />
            <Label for={`${id}-c`}>Ink the outline</Label>
          </div>
          <div class="flex items-center gap-2">
            <Switch id={`${id}-s`} defaultChecked />
            <Label for={`${id}-s`}>Share with the club</Label>
          </div>
          <Progress value={64} aria-label="Pages done" />
        </Paper>
      </div>
    </InkProvider>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef, useId } from "vue";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { CodeBlock } from "@/components/ui/code-block";
import { Field, FieldContent, FieldDescription, FieldGroup, FieldLabel, FieldLegend, FieldSet, FieldTitle } from "@/components/ui/field";
import { Icon } from "@/components/ui/icon";
import { Page, PageDescription, PageHeader, PageTitle } from "@/components/ui/page";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { DEFAULT_APPEARANCE, DENSITIES, MOTIONS, PAPERS, THEMES, providerSnippet, type Appearance, type Density, type Direction, type Motion, type PaperChoice } from "@/blocks/settings-appearance/components/settings-appearance-options";
import { SettingsAppearancePreview } from "@/blocks/settings-appearance/components/settings-appearance-preview";
import { cn } from "@/lib/utils";
type Props = {
  className?: string;
  value?: Appearance;
  defaultValue?: Appearance;
  onValueChange?: (value: Appearance) => void;
};
const SettingsAppearance = defineUi<Props>("SettingsAppearance", ["class", "value", "defaultValue", "onValueChange"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const value = computed(() => _props["value"]);
  const defaultValue = computed(() => _props["defaultValue"] === undefined ? DEFAULT_APPEARANCE : _props["defaultValue"]);
  const onValueChange = computed(() => _props["onValueChange"]);
  const inner = shallowRef<Appearance>(initialState(defaultValue.value));
  const setInner = stateSetter(inner);
  const a = computed(() => value.value ?? inner.value);
  const ids = useId();
  const set = computed(() => (patch: Partial<Appearance>) => {
    const next = {
      ...a.value,
      ...patch
    };
    if (value.value === undefined) setInner(next);
    onValueChange.value?.(next);
  });
  const isDefault = computed(() => JSON.stringify(a.value) === JSON.stringify(DEFAULT_APPEARANCE));
  return () => {
    return <div class="w-full overflow-x-clip px-2">
      <Page as="section" width="xl" holes="top" seed="settings-appearance" aria-labelledby={`${ids}-title`} class={cn("my-6", className.value)}>
        <PageHeader>
          <PageTitle as="h2" id={`${ids}-title`} underline="highlight" seed="appearance-title">
            Appearance
          </PageTitle>
          <PageDescription>How the desk feels. Choices apply to the preview straight away; the code below is what to give your own provider.</PageDescription>
        </PageHeader>

        <div class="@container/appearance">
          <div class="grid items-start gap-10 @4xl/appearance:grid-cols-[minmax(0,1fr)_22rem]">
            <div class="@container/opts">
              <FieldGroup class="gap-8">
                <FieldSet>
                  <FieldLegend>Theme</FieldLegend>
                  <RadioGroup value={a.value.theme} onValueChange={theme => set.value({
                    theme
                  })} aria-label="Theme" class="gap-3 @xl/opts:grid-cols-3">
                    {THEMES.map(t => <FieldLabel key={t.id} for={`${ids}-theme-${t.id}`}>
                        <Field orientation="horizontal" data-disabled={t.ready ? undefined : true}>
                          <FieldContent>
                            <FieldTitle class="flex-wrap">
                              {t.name}
                              {t.ready ? null : <Badge size="sm" variant="outline">
                                  soon
                                </Badge>}
                            </FieldTitle>
                            <FieldDescription>{t.help}</FieldDescription>
                          </FieldContent>
                          <RadioGroupItem value={t.id} id={`${ids}-theme-${t.id}`} disabled={!t.ready} />
                        </Field>
                      </FieldLabel>)}
                  </RadioGroup>
                </FieldSet>

                <FieldSet>
                  <FieldLegend>Density</FieldLegend>
                  <RadioGroup value={a.value.density} onValueChange={v => set.value({
                    density: v as Density
                  })} aria-label="Density" class="gap-3">
                    {DENSITIES.map(d => <FieldLabel key={d.id} for={`${ids}-density-${d.id}`}>
                        <Field orientation="horizontal">
                          <FieldContent>
                            <FieldTitle>{d.name}</FieldTitle>
                            <FieldDescription>{d.help}</FieldDescription>
                          </FieldContent>
                          <RadioGroupItem value={d.id} id={`${ids}-density-${d.id}`} />
                        </Field>
                      </FieldLabel>)}
                  </RadioGroup>
                </FieldSet>

                <FieldSet>
                  <FieldLegend>Motion</FieldLegend>
                  <RadioGroup value={a.value.motion} onValueChange={v => set.value({
                    motion: v as Motion
                  })} aria-label="Motion" class="gap-3 @lg/opts:grid-cols-2">
                    {MOTIONS.map(m => <FieldLabel key={m.id} for={`${ids}-motion-${m.id}`}>
                        <Field orientation="horizontal">
                          <FieldContent>
                            <FieldTitle>{m.name}</FieldTitle>
                            <FieldDescription>{m.help}</FieldDescription>
                          </FieldContent>
                          <RadioGroupItem value={m.id} id={`${ids}-motion-${m.id}`} />
                        </Field>
                      </FieldLabel>)}
                  </RadioGroup>
                </FieldSet>

                <Separator variant="dashed" />

                <Field orientation="horizontal">
                  <FieldContent>
                    <FieldLabel for={`${ids}-fine`}>Fine ink</FieldLabel>
                    <FieldDescription>Draws with more strokes. Lovely on a big screen, heavier on a small phone.</FieldDescription>
                  </FieldContent>
                  <Switch id={`${ids}-fine`} checked={a.value.fine} onCheckedChange={fine => set.value({
                    fine
                  })} />
                </Field>

                <Field>
                  <FieldLabel id={`${ids}-paper`}>Paper for the preview</FieldLabel>
                  <ToggleGroup type="single" variant="outline" aria-labelledby={`${ids}-paper`} value={a.value.paper} onValueChange={v => v && set.value({
                    paper: v as PaperChoice
                  })} class="w-fit! flex-wrap">
                    {PAPERS.map(p => <ToggleGroupItem key={p.id} value={p.id}>
                        {p.name}
                      </ToggleGroupItem>)}
                  </ToggleGroup>
                </Field>

                <Field>
                  <FieldLabel id={`${ids}-dir`}>Reading direction</FieldLabel>
                  <ToggleGroup type="single" variant="outline" aria-labelledby={`${ids}-dir`} value={a.value.dir} onValueChange={v => v && set.value({
                    dir: v as Direction
                  })} class="w-fit!">
                    <ToggleGroupItem value="ltr">Left to right</ToggleGroupItem>
                    <ToggleGroupItem value="rtl">Right to left</ToggleGroupItem>
                  </ToggleGroup>
                  <FieldDescription>Margins, tabs and arrows turn round; the handwriting does not.</FieldDescription>
                </Field>

                <div>
                  <Button type="button" variant="outline" onClick={() => set.value(DEFAULT_APPEARANCE)} aria-disabled={isDefault.value}>
                    <Icon name="rotate-cw" />
                    Back to the defaults
                  </Button>
                </div>
              </FieldGroup>
            </div>

            <div class="grid gap-6 @4xl/appearance:sticky @4xl/appearance:top-6">
              <SettingsAppearancePreview appearance={a.value} />
              <div class="grid gap-2">
                <p class="font-script text-2xl leading-none font-semibold">Your provider</p>
                <CodeBlock code={providerSnippet(a.value)} language="tsx" filename="root.tsx" wrap seed="appearance-snippet" />
              </div>
            </div>
          </div>
        </div>
      </Page>
    </div>;
  };
});
export default SettingsAppearance;
